        create:
          "DO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1\n    FROM pg_constraint c\n    JOIN pg_class t ON t.oid = c.conrelid\n    JOIN pg_namespace n ON n.oid = t.relnamespace\n    WHERE c.conname = 'user_uuid_required_for_non_registration_tokens'\n      AND t.relname = 'phoenix_kit_users_tokens'\n      AND n.nspname = '__SCHEMA__'\n  ) THEN\n    ALTER TABLE __SCHEMA__.phoenix_kit_users_tokens ADD CONSTRAINT user_uuid_required_for_non_registration_tokens CHECK (\nCASE\n    WHEN ((context)::text = 'magic_link_registration'::text) THEN true\n    ELSE (user_uuid IS NOT NULL)\nEND);\n  END IF;\nEND\n$$",
