  defp raw_data_invariants do
    [
      %{
        desc: "V77: tickets_* settings keys were renamed; none may remain",
        since: 77,
        assert:
          "SELECT NOT EXISTS (SELECT 1 FROM __SCHEMA__.phoenix_kit_settings WHERE key IN ('tickets_enabled','tickets_per_page','tickets_comments_enabled','tickets_internal_notes_enabled','tickets_attachments_enabled','tickets_allow_reopen','auto_granted_perm:tickets'))"
      },
      %{
        desc: "V109: customer_service_* settings keys renamed to customer_support_*",
        since: 109,
        assert:
          "SELECT NOT EXISTS (SELECT 1 FROM __SCHEMA__.phoenix_kit_settings WHERE key LIKE 'customer_service_%')"
      },
      %{
        desc: "V109: role_permissions module_key uses customer_support",
        since: 109,
        assert:
          "SELECT NOT EXISTS (SELECT 1 FROM __SCHEMA__.phoenix_kit_role_permissions WHERE module_key IN ('tickets', 'customer_service'))"
      },
      %{
        desc: "V114: settings integration rows are uuid-keyed; no composite integration:* keys",
        since: 114,
        assert:
          "SELECT NOT EXISTS (SELECT 1 FROM __SCHEMA__.phoenix_kit_settings WHERE key LIKE 'integration:%')"
      },
      %{
        desc: "V137: email_logs.aws_message_id unique among non-NULL values",
        since: 137,
        assert:
          "SELECT NOT EXISTS (SELECT 1 FROM __SCHEMA__.phoenix_kit_email_logs WHERE aws_message_id IS NOT NULL GROUP BY aws_message_id HAVING COUNT(*) > 1)"
      },
      %{
        desc: "V137: email_events deduplicated for single-occurrence event types",
        since: 137,
        assert:
          "SELECT NOT EXISTS (SELECT 1 FROM __SCHEMA__.phoenix_kit_email_events WHERE event_type NOT IN ('open','click') GROUP BY email_log_uuid, event_type HAVING COUNT(*) > 1)"
      }
    ]
  end
end
